 30	package com.pousada.marealta.config;
 31	
 32	import java.sql.Connection;
 33	import java.sql.DriverManager;
 34	import java.sql.SQLException;
 35	
 36	public class DatabaseConfig {
 37	    private static String dbUrl;
 38	    private static String dbUser;
 39	    private static String dbPassword;
 40	
 41	    static {
 42	        dbUrl = System.getenv("DB_URL");
 43	        dbUser = System.getenv("DB_USER");
 44	        dbPassword = System.getenv("DB_PASSWORD");
 45	
 46	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 47	            throw new RuntimeException("Database configuration missing: DB_URL, DB_USER, DB_PASSWORD");
 48	        }
 49	    }
 50	
 51	    public static void initialize() {
 52	        try (Connection conn = getConnection()) {
 53	            createSchema(conn);
 54	        } catch (SQLException e) {
 55	            throw new RuntimeException("Failed to initialize database", e);
 56	        }
 57	    }
 58	
 59	    public static Connection getConnection() throws SQLException {
 60	        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
 61	    }
 62	
 63	    private static void createSchema(Connection conn) throws SQLException {
 64	        String[] statements = {
 65	            """
 66	            CREATE TABLE IF NOT EXISTS rooms (
 67	                number INTEGER PRIMARY KEY,
 68	                type VARCHAR(20) NOT NULL,
 69	                capacity INTEGER NOT NULL,
 70	                nightly_rate NUMERIC(10, 2) NOT NULL
 71	            )
 72	            """,
 73	            """
 74	            CREATE TABLE IF NOT EXISTS reservations (
 75	                id BIGSERIAL PRIMARY KEY,
 76	                room_number INTEGER NOT NULL REFERENCES rooms(number),
 77	                guest_name VARCHAR(255) NOT NULL,
 78	                guest_email VARCHAR(255) NOT NULL,
 79	                guest_cpf VARCHAR(20) NOT NULL,
 80	                check_in DATE NOT NULL,
 81	                check_out DATE NOT NULL,
 82	                guests INTEGER NOT NULL,
 83	                rate_plan VARCHAR(20) NOT NULL,
 84	                nights INTEGER NOT NULL,
 85	                subtotal NUMERIC(10, 2) NOT NULL,
 86	                discount NUMERIC(10, 2),
 87	                total NUMERIC(10, 2) NOT NULL,
 88	                status VARCHAR(20) NOT NULL,
 89	                amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 90	                refund NUMERIC(10, 2)
 91	            )
 92	            """,
 93	            """
 94	            CREATE TABLE IF NOT EXISTS messages (
 95	                id BIGSERIAL PRIMARY KEY,
 96	                channel VARCHAR(20) NOT NULL,
 97	                to_address VARCHAR(255) NOT NULL,
 98	                subject VARCHAR(255) NOT NULL,
 99	                body TEXT NOT NULL
100	            )
101	            """,
102	            """
103	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
104	            (101, 'STANDARD', 2, 249.90),
105	            (102, 'STANDARD', 2, 249.90),
106	            (201, 'DELUXE', 3, 389.90),
107	            (202, 'DELUXE', 3, 389.90),
108	            (301, 'SUITE', 4, 579.90)
109	            ON CONFLICT (number) DO NOTHING
110	            """
111	        };
112	
113	        for (String sql : statements) {
114	            if (!sql.trim().isEmpty()) {
115	                try (var stmt = conn.createStatement()) {
116	                    stmt.execute(sql);
117	                }
118	            }
119	        }
120	    }
121	}

