  1	package com.pousada.marealta.controller;
  2	
  3	import com.google.gson.JsonSyntaxException;
  4	import com.pousada.marealta.domain.Reservation;
  5	import com.pousada.marealta.domain.ReservationDocument;
  6	import com.pousada.marealta.notification.NotificationService;
  7	import com.pousada.marealta.repository.MessageRepository;
  8	import com.pousada.marealta.repository.ReservationRepository;
  9	import com.pousada.marealta.repository.RoomRepository;
 10	import com.pousada.marealta.service.ReservationService;
 11	import com.pousada.marealta.util.DateFormatter;
 12	import com.pousada.marealta.util.MoneyFormatter;
 13	import io.javalin.Javalin;
 14	
 15	import java.sql.SQLException;
 16	import java.time.LocalDate;
 17	import java.time.format.DateTimeParseException;
 18	
 19	public class ReservationController {
 20	    private static final ReservationRepository reservationRepository = new ReservationRepository();
 21	    private static final RoomRepository roomRepository = new RoomRepository();
 22	    private static final NotificationService notificationService = NotificationService.getInstance();
 23	
 24	    private static final ReservationService reservationService =
 25	        new ReservationService(reservationRepository, roomRepository, notificationService);
 26	
 27	    public static void register(Javalin app) {
 28	        app.post("/reservations", ctx -> {
 29	            try {
 30	                var req = ctx.bodyAsClass(CreateReservationRequest.class);
 31	                validateCreateRequest(req);
 32	
 33	                LocalDate checkIn = LocalDate.parse(req.checkIn);
 34	                LocalDate checkOut = LocalDate.parse(req.checkOut);
 35	
 36	                Reservation reservation = reservationService.create(
 37	                    req.roomNumber,
 38	                    req.guestName,
 39	                    req.guestEmail,
 40	                    req.guestCpf,
 41	                    checkIn,
 42	                    checkOut,
 43	                    req.guests,
 44	                    Reservation.RatePlan.valueOf(req.ratePlan)
 45	                );
 46	
 47	                ctx.status(201);
 48	                ctx.json(toResponse(reservation));
 49	            } catch (ReservationService.RoomNotFoundException e) {
 50	                ctx.status(404);
 51	                ctx.json(error("ROOM_NOT_FOUND", "Room not found"));
 52	            } catch (ReservationService.CapacityExceededException e) {
 53	                ctx.status(422);
 54	                ctx.json(error("CAPACITY_EXCEEDED", "Too many guests for this room"));
 55	            } catch (ReservationService.RoomUnavailableException e) {
 56	                ctx.status(409);
 57	                ctx.json(error("ROOM_UNAVAILABLE", "Room is not available for the requested dates"));
 58	            } catch (ReservationService.InvalidOperationException e) {
 59	                ctx.status(400);
 60	                ctx.json(error(e.getCode(), "Invalid request"));
 61	            } catch (DateTimeParseException e) {
 62	                ctx.status(400);
 63	                ctx.json(error("INVALID_REQUEST", "Invalid date format"));
 64	            } catch (JsonSyntaxException e) {
 65	                ctx.status(400);
 66	                ctx.json(error("INVALID_REQUEST", "Invalid request body"));
 67	            } catch (SQLException e) {
 68	                ctx.status(500);
 69	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
 70	            }
 71	        });
 72	
 73	        app.get("/reservations/{id}", ctx -> {
 74	            try {
 75	                long id = Long.parseLong(ctx.pathParam("id"));
 76	                Reservation reservation = reservationRepository.findById(id);
 77	
 78	                if (reservation == null) {
 79	                    ctx.status(404);
 80	                    ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
 81	                    return;
 82	                }
 83	
 84	                ctx.json(toResponse(reservation));
 85	            } catch (NumberFormatException e) {
 86	                ctx.status(400);
 87	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
 88	            } catch (SQLException e) {
 89	                ctx.status(500);
 90	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
 91	            }
 92	        });
 93	
 94	        app.post("/reservations/{id}/confirmation", ctx -> {
 95	            try {
 96	                long id = Long.parseLong(ctx.pathParam("id"));
 97	                Reservation reservation = reservationService.confirm(id);
 98	                ctx.json(toResponse(reservation));
 99	            } catch (ReservationService.ReservationNotFoundException e) {
100	                ctx.status(404);
101	                ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
102	            } catch (ReservationService.InvalidOperationException e) {
103	                ctx.status(409);
104	                ctx.json(error(e.getCode(), "Cannot confirm this reservation"));
105	            } catch (NumberFormatException e) {
106	                ctx.status(400);
107	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
108	            } catch (SQLException e) {
109	                ctx.status(500);
110	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
111	            }
112	        });
113	
114	        app.post("/reservations/{id}/cancellation", ctx -> {
115	            try {
116	                long id = Long.parseLong(ctx.pathParam("id"));
117	                Reservation reservation = reservationService.cancel(id);
118	                ctx.json(toResponse(reservation));
119	            } catch (ReservationService.ReservationNotFoundException e) {
120	                ctx.status(404);
121	                ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
122	            } catch (ReservationService.InvalidOperationException e) {
123	                ctx.status(409);
124	                ctx.json(error(e.getCode(), "Cannot cancel this reservation"));
125	            } catch (NumberFormatException e) {
126	                ctx.status(400);
127	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
128	            } catch (SQLException e) {
129	                ctx.status(500);
130	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
131	            }
132	        });
133	
134	        app.post("/reservations/{id}/check-in", ctx -> {
135	            try {
136	                long id = Long.parseLong(ctx.pathParam("id"));
137	                Reservation reservation = reservationService.checkIn(id);
138	                ctx.json(toResponse(reservation));
139	            } catch (ReservationService.ReservationNotFoundException e) {
140	                ctx.status(404);
141	                ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
142	            } catch (ReservationService.InvalidOperationException e) {
143	                ctx.status(409);
144	                ctx.json(error(e.getCode(), "Cannot check in this reservation"));
145	            } catch (NumberFormatException e) {
146	                ctx.status(400);
147	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
148	            } catch (SQLException e) {
149	                ctx.status(500);
150	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
151	            }
152	        });
153	
154	        app.post("/reservations/{id}/check-out", ctx -> {
155	            try {
156	                long id = Long.parseLong(ctx.pathParam("id"));
157	                Reservation reservation = reservationService.checkOut(id);
158	                ReservationDocument doc = buildDocument(reservation);
159	                ctx.json(documentToResponse(doc));
160	            } catch (ReservationService.ReservationNotFoundException e) {
161	                ctx.status(404);
162	                ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
163	            } catch (ReservationService.InvalidOperationException e) {
164	                ctx.status(409);
165	                ctx.json(error(e.getCode(), "Cannot check out this reservation"));
166	            } catch (NumberFormatException e) {
167	                ctx.status(400);
168	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
169	            } catch (SQLException e) {
170	                ctx.status(500);
171	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
172	            }
173	        });
174	
175	        app.get("/reservations/{id}/document", ctx -> {
176	            try {
177	                long id = Long.parseLong(ctx.pathParam("id"));
178	                Reservation reservation = reservationRepository.findById(id);
179	
180	                if (reservation == null) {
181	                    ctx.status(404);
182	                    ctx.json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
183	                    return;
184	                }
185	
186	                if (reservation.getStatus() == Reservation.ReservationStatus.PENDING) {
187	                    ctx.status(409);
188	                    ctx.json(error("OPERATION_NOT_ALLOWED", "Document only available for confirmed reservations"));
189	                    return;
190	                }
191	
192	                ReservationDocument doc = buildDocument(reservation);
193	                ctx.json(documentToResponse(doc));
194	            } catch (NumberFormatException e) {
195	                ctx.status(400);
196	                ctx.json(error("INVALID_REQUEST", "Invalid reservation ID"));
197	            } catch (SQLException e) {
198	                ctx.status(500);
199	                ctx.json(error("DATABASE_ERROR", e.getMessage()));
200	            }
201	        });
202	    }
203	
204	    private static void validateCreateRequest(CreateReservationRequest req) {
205	        if (req.roomNumber == 0 || req.guestName == null || req.guestEmail == null ||
206	            req.guestCpf == null || req.checkIn == null || req.checkOut == null ||
207	            req.guests == 0 || req.ratePlan == null) {
208	            throw new ReservationService.InvalidOperationException("INVALID_REQUEST");
209	        }
210	    }
211	
212	    private static Object toResponse(Reservation res) {
213	        return new Object() {
214	            public final long id = res.getId();
215	            public final int roomNumber = res.getRoomNumber();
216	            public final String guestName = res.getGuestName();
217	            public final String guestEmail = res.getGuestEmail();
218	            public final String guestCpf = res.getGuestCpf();
219	            public final String checkIn = DateFormatter.format(res.getCheckIn());
220	            public final String checkOut = DateFormatter.format(res.getCheckOut());
221	            public final int guests = res.getGuests();
222	            public final String ratePlan = res.getRatePlan().name();
223	            public final int nights = res.getNights();
224	            public final Object subtotal = res.getSubtotal();
225	            public final Object discount = res.getDiscount();
226	            public final Object total = res.getTotal();
227	            public final String status = res.getStatus().name();
228	            public final Object amountPaid = res.getAmountPaid();
229	            public final Object refund = res.getRefund();
230	        };
231	    }
232	
233	    private static Object documentToResponse(ReservationDocument doc) {
234	        return new Object() {
235	            public final String title = doc.getTitle();
236	            public final long reservationId = doc.getReservationId();
237	            public final String guestName = doc.getGuestName();
238	            public final String guestCpf = doc.getGuestCpf();
239	            public final int roomNumber = doc.getRoomNumber();
240	            public final String roomType = doc.getRoomType();
241	            public final String checkIn = DateFormatter.format(doc.getCheckIn());
242	            public final String checkOut = DateFormatter.format(doc.getCheckOut());
243	            public final int nights = doc.getNights();
244	            public final Object subtotal = doc.getSubtotal();
245	            public final Object discount = doc.getDiscount();
246	            public final Object total = doc.getTotal();
247	        };
248	    }
249	
250	    private static ReservationDocument buildDocument(Reservation res) throws SQLException {
251	        var room = roomRepository.findByNumber(res.getRoomNumber());
252	        String roomType = room != null ? room.getType().name() : "UNKNOWN";
253	
254	        return new ReservationDocument(
255	            res.getId(),
256	            res.getGuestName(),
257	            res.getGuestCpf(),
258	            res.getRoomNumber(),
259	            roomType,
260	            res.getCheckIn(),
261	            res.getCheckOut(),
262	            res.getNights(),
263	            res.getSubtotal(),
264	            res.getDiscount(),
265	            res.getTotal()
266	        );
267	    }
268	
269	    private static Object error(String code, String message) {
270	        String errorCode = code;
271	        String errorMessage = message;
272	        return new Object() {
273	            public final String error = errorCode;
274	            public final String message = errorMessage;
275	        };
276	    }
277	
278	    public static class CreateReservationRequest {
279	        public int roomNumber;
280	        public String guestName;
281	        public String guestEmail;
282	        public String guestCpf;
283	        public String checkIn;
284	        public String checkOut;
285	        public int guests;
286	        public String ratePlan;
287	    }
288	}

