187	            .guestName(reservation.getGuestName())
188	            .guestEmail(reservation.getGuestEmail())
189	            .guestCpf(reservation.getGuestCpf())
190	            .checkIn(reservation.getCheckIn())
191	            .checkOut(reservation.getCheckOut())
