207	    private void validateDates(LocalDate checkIn, LocalDate checkOut) {
208	        if (!checkOut.isAfter(checkIn)) {
209	            throw new InvalidOperationException("INVALID_REQUEST");
210	        }
211	    }
212	
213	    private void validateGuests(int guests) {
214	        if (guests < 1) {
215	            throw new InvalidOperationException("INVALID_REQUEST");
216	        }
217	    }
