109	        java.math.BigDecimal refund = java.math.BigDecimal.ZERO;
110	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
111	            refund = reservation.getRatePlan() == Reservation.RatePlan.STANDARD
112	                ? reservation.getAmountPaid()
113	                : java.math.BigDecimal.ZERO;
114	        }
115	
116	        var updated = new Reservation.Builder()
117	            .id(reservation.getId())
118	            .roomNumber(reservation.getRoomNumber())
119	            .guestName(reservation.getGuestName())
120	            .guestEmail(reservation.getGuestEmail())
121	            .guestCpf(reservation.getGuestCpf())
122	            .checkIn(reservation.getCheckIn())
123	            .checkOut(reservation.getCheckOut())
124	            .guests(reservation.getGuests())
125	            .ratePlan(reservation.getRatePlan())
126	            .nights(reservation.getNights())
127	            .subtotal(reservation.getSubtotal())
128	            .discount(reservation.getDiscount())
129	            .total(reservation.getTotal())
130	            .status(ReservationStatus.CANCELLED)
131	            .amountPaid(reservation.getAmountPaid())
132	            .refund(refund.signum() > 0 ? refund : null)
133	            .build();
134	
135	        reservationRepository.update(updated);
136	        notificationService.notifyReservationCancelled(updated);
137	
138	        return updated;
139	    }
