255	package com.pousada.marealta.service;
256	
257	import com.pousada.marealta.domain.Reservation;
258	import com.pousada.marealta.domain.Room;
259	import com.pousada.marealta.util.MathUtil;
260	
261	import java.math.BigDecimal;
262	import java.time.LocalDate;
263	import java.time.YearMonth;
264	
265	public class PricingService {
266	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.2);
267	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = BigDecimal.valueOf(0.15);
268	
269	    public static PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut,
270	                                               Reservation.RatePlan ratePlan) {
271	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
272	
273	        BigDecimal nightly = room.getNightlyRate();
274	        if (isHighSeason(checkIn, checkOut)) {
275	            nightly = MathUtil.roundHalfEven(nightly.multiply(HIGH_SEASON_MULTIPLIER));
276	        }
277	
278	        BigDecimal subtotal = MathUtil.roundHalfEven(nightly.multiply(BigDecimal.valueOf(nights)));
279	
280	        BigDecimal discount = BigDecimal.ZERO;
281	        if (ratePlan == Reservation.RatePlan.NON_REFUNDABLE) {
282	            discount = MathUtil.roundHalfEven(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
283	        }
284	
285	        BigDecimal total = MathUtil.roundHalfEven(subtotal.subtract(discount));
286	
287	        return new PricingResult(nights, subtotal, discount, total);
288	    }
289	
290	    private static boolean isHighSeason(LocalDate checkIn, LocalDate checkOut) {
291	        LocalDate current = checkIn;
292	
293	        while (current.isBefore(checkOut)) {
294	            int month = current.getMonthValue();
295	            int dayOfMonth = current.getDayOfMonth();
296	
297	            if ((month == 7) ||
298	                (month == 12 && dayOfMonth >= 15) ||
299	                (month == 1) ||
300	                (month == 2)) {
301	                return true;
302	            }
303	
304	            current = current.plusDays(1);
305	        }
306	
307	        return false;
308	    }
309	
310	    public static class PricingResult {
311	        public final int nights;
312	        public final BigDecimal subtotal;
313	        public final BigDecimal discount;
314	        public final BigDecimal total;
315	
316	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
317	            this.nights = nights;
318	            this.subtotal = subtotal;
319	            this.discount = discount;
320	            this.total = total;
321	        }
322	    }
323	}

