   146	            FROM reservations
   147	            WHERE check_in >= ? AND check_in <= ?
   148	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
   149	            ORDER BY check_in ASC, id ASC
