    94	            AND status NOT IN ('CANCELLED')
    95	            AND check_in < ?
    96	            AND check_out > ?
    97	            """;
    98	
    99	        try (var conn = DatabaseConfig.getConnection();
   100	             var stmt = conn.prepareStatement(sql)) {
   101	            stmt.setInt(1, roomNumber);
   102	            stmt.setObject(2, checkOut);
   103	            stmt.setObject(3, checkIn);
