   114	    public List<Reservation> findByRoomAndDate(int roomNumber, LocalDate date) throws SQLException {
   115	        String sql = """
   116	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
   117	                   rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
   118	            FROM reservations
   119	            WHERE room_number = ? AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   120	            AND check_in <= ? AND check_out > ?
   121	            """;
   122	
   123	        List<Reservation> reservations = new ArrayList<>();
   124	        try (var conn = DatabaseConfig.getConnection();
   125	             var stmt = conn.prepareStatement(sql)) {
   126	            stmt.setInt(1, roomNumber);
   127	            stmt.setObject(2, date);
   128	            stmt.setObject(3, date);
   129	            try (var rs = stmt.executeQuery()) {
   130	                while (rs.next()) {
   131	                    reservations.add(buildReservation(rs));
   132	                }
   133	            }
   134	        }
   135	
   136	        return reservations;
