   139	    public List<Reservation> findByMonth(int year, int month) throws SQLException {
   140	        LocalDate startOfMonth = LocalDate.of(year, month, 1);
   141	        LocalDate endOfMonth = startOfMonth.plusMonths(1).minusDays(1);
   142	
   143	        String sql = """
   144	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
   145	                   rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
   146	            FROM reservations
   147	            WHERE check_in >= ? AND check_in <= ?
   148	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED')
   149	            ORDER BY check_in ASC, id ASC
   150	            """;
   151	
   152	        List<Reservation> reservations = new ArrayList<>();
   153	        try (var conn = DatabaseConfig.getConnection();
   154	             var stmt = conn.prepareStatement(sql)) {
   155	            stmt.setObject(1, startOfMonth);
   156	            stmt.setObject(2, endOfMonth);
   157	            try (var rs = stmt.executeQuery()) {
   158	                while (rs.next()) {
   159	                    reservations.add(buildReservation(rs));
   160	                }
   161	            }
   162	        }
   163	
   164	        return reservations;
   165	    }
