   167	    private Reservation buildReservation(java.sql.ResultSet rs) throws SQLException {
   168	        return new Reservation.Builder()
   169	            .id(rs.getLong("id"))
   170	            .roomNumber(rs.getInt("room_number"))
   171	            .guestName(rs.getString("guest_name"))
   172	            .guestEmail(rs.getString("guest_email"))
   173	            .guestCpf(rs.getString("guest_cpf"))
   174	            .checkIn(rs.getObject("check_in", LocalDate.class))
   175	            .checkOut(rs.getObject("check_out", LocalDate.class))
   176	            .guests(rs.getInt("guests"))
   177	            .ratePlan(RatePlan.valueOf(rs.getString("rate_plan")))
   178	            .nights(rs.getInt("nights"))
   179	            .subtotal(rs.getBigDecimal("subtotal"))
   180	            .discount(rs.getBigDecimal("discount"))
   181	            .total(rs.getBigDecimal("total"))
   182	            .status(ReservationStatus.valueOf(rs.getString("status")))
   183	            .amountPaid(rs.getBigDecimal("amount_paid"))
   184	            .refund(rs.getObject("refund", java.math.BigDecimal.class))
   185	            .build();
   186	    }
