    10	public class DocumentFormatter {
    11	    private static final RoomRepository roomRepository = new RoomRepository();
    12	
    13	    public static String format(Reservation reservation) {
    14	        try {
    15	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
    16	            String roomType = room.getType().name();
    17	
    18	            StringBuilder doc = new StringBuilder();
    19	            doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    20	            doc.append("Hóspede: ").append(reservation.getGuestName())
    21	                    .append(" (CPF ").append(reservation.getGuestCpf()).append(")\n");
    22	            doc.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(roomType).append(")\n");
    23	
    24	            String nightsLabel = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
    25	            doc.append("Entrada: ").append(DateFormatter.format(reservation.getCheckIn()))
    26	                    .append(" | Saída: ").append(DateFormatter.format(reservation.getCheckOut()))
    27	                    .append(" | ").append(nightsLabel).append("\n");
    28	
    29	            doc.append("Diárias: ").append(MoneyFormatter.format(reservation.getSubtotal())).append("\n");
    30	
    31	            if (reservation.getDiscount() != null && reservation.getDiscount().signum() > 0) {
    32	                doc.append("Desconto: ").append(MoneyFormatter.format(reservation.getDiscount())).append("\n");
    33	            }
    34	
    35	            doc.append("Total: ").append(MoneyFormatter.format(reservation.getTotal())).append("\n");
    36	
    37	            return doc.toString().trim();
    38	        } catch (SQLException e) {
    39	            throw new RuntimeException("Failed to format document", e);
    40	        }
    41	    }
    42	}
